const icon=(n,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round">${ICONS[n]||ICONS.chevron}</svg>`;

const state={route:'dashboard',boot:null,items:[],partners:[],invoice:{sale:null,purchase:null},currentPrint:null,partnerType:'Customer'};
function storageGet(k){try{return window.localStorage.getItem(k)}catch(e){console.warn('localStorage unavailable:',e.message);return null}}
function storageSet(k,v){try{window.localStorage.setItem(k,v)}catch(e){console.warn('localStorage unavailable:',e.message)}}
const nav=[
 ['dashboard','الرئيسية','dashboard'],['items','الأصناف والمخزون','items'],['partners','العملاء والموردون','users'],['sales','المبيعات ونقطة البيع','sales'],['purchases','المشتريات','purchase'],['vouchers','سندات القبض والصرف','voucher'],['accounts','شجرة الحسابات والقيود','accounts'],['reports','التقارير والمزامنة','reports'],['settings','الإعدادات والكليشة','settings']
];

async function api(path,opts={}){
 const res=await fetch('/api'+path,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts,body:opts.body&&typeof opts.body!=='string'?JSON.stringify(opts.body):opts.body});
 let data; try{data=await res.json()}catch(e){throw new Error(`استجابة غير صالحة من الخادم (${res.status})`)}
 if(!res.ok||!data.ok) throw new Error(data.error||`فشل الطلب ${res.status}`); return data.data;
}
function busy(on=true){$('#loading').classList.toggle('hidden',!on)}
function toast(title,msg='',type='success',ms=4200){
 const el=document.createElement('div'); el.className=`toast ${type}`; el.innerHTML=`${icon(type==='error'?'alert':'check')}<div><strong>${esc(title)}</strong>${msg?`<p>${esc(msg)}</p>`:''}</div>`; $('#toastRoot').append(el); setTimeout(()=>el.remove(),ms);
}
async function run(fn,{loading=false}={}){try{if(loading)busy(true);return await fn()}catch(e){console.error(e);toast('تعذر تنفيذ العملية',e.message||String(e),'error',7000);throw e}finally{if(loading)busy(false)}}
function btnIconize(root=document){$$('[data-icon]',root).forEach(b=>{if(!b.querySelector('svg'))b.insertAdjacentHTML('afterbegin',icon(b.dataset.icon))})}
function modal(title,body,{wide=false,small=false,foot='',onOpen=null}={}){
 const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal ${wide?'wide':''} ${small?'small':''}"><div class="modal-head"><h2>${title}</h2><button class="icon-only ghost modal-close" data-icon="close" aria-label="إغلاق"></button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div>`;
 $('#modalRoot').append(wrap);btnIconize(wrap);const close=()=>wrap.remove();$('.modal-close',wrap).onclick=close;wrap.addEventListener('mousedown',e=>{if(e.target===wrap)close()});if(onOpen)onOpen(wrap,close);return {el:wrap,close};
}
const opt=(arr,valKey='id',labelKey='name',selected='')=>arr.map(x=>`<option value="${esc(x[valKey])}" ${String(x[valKey])===String(selected)?'selected':''}>${esc(x[labelKey])}</option>`).join('');
const accountByCode=code=>state.boot.accounts.find(a=>a.code===code);
const postable=()=>state.boot.accounts.filter(a=>a.postable&&a.active);
const cashAccounts=()=>state.boot.accounts.filter(a=>['1110','1120'].includes(a.code));
function pageHead(title,desc,actions=''){return `<div class="page-head"><div class="page-title"><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function empty(msg='لا توجد بيانات'){return `<div class="empty">${icon('file')}<p>${msg}</p></div>`}

async function loadBoot(){state.boot=await api('/bootstrap');const s=state.boot.settings;$('#brandName').textContent=s.arabic_name||'كودينكس';$('#companyTop').textContent=s.arabic_name||'كودينكس';$('#companyAvatar').textContent=(s.arabic_name||'ق').trim()[0];if(s.dark_mode)document.documentElement.dataset.theme='dark'}
function buildNav(){const el=$('#nav');el.innerHTML=nav.map(([id,label,ic])=>`<button class="nav-item ${state.route===id?'active':''}" data-route="${id}">${icon(ic)}<span>${label}</span></button>`).join('');$$('[data-route]',el).forEach(b=>b.onclick=()=>navigate(b.dataset.route))}
async function navigate(route){state.route=route;buildNav();$('#sidebar').classList.remove('open');await render()}

async function render(){const v=$('#view');v.innerHTML='<div class="empty">جارٍ التحميل...</div>';const map={dashboard:renderDashboard,items:renderItems,partners:renderPartners,sales:()=>renderInvoice('sale'),purchases:()=>renderInvoice('purchase'),vouchers:renderVouchers,accounts:renderAccounts,reports:renderReports,settings:renderSettings};await run(map[state.route]||renderDashboard);btnIconize(v)}

async function renderDashboard(){const x=await api('/dashboard');const s=state.boot.settings;$('#view').innerHTML=pageHead('لوحة القيادة','صورة مالية لحظية من قاعدة SQLite المحلية',`<button data-route-go="sales" data-icon="plus">فاتورة مبيعات</button><button class="ghost" data-route-go="vouchers" data-icon="receipt">سند قبض</button><button class="ghost" data-route-go="accounts" data-icon="accounts">قيد يومية</button>`)+`
 <div class="grid kpi-grid">
 ${kpi('مبيعات اليوم',x.sales,s.currency_symbol,'sales','blue')}${kpi('مشتريات اليوم',x.purchases,s.currency_symbol,'purchase','orange')}${kpi('الصندوق والبنوك',x.cash,s.currency_symbol,'cash','green')}${kpi('قيمة المخزون',x.inventory,s.currency_symbol,'box','violet')}${kpi('ذمم العملاء',x.receivables,s.currency_symbol,'users','cyan')}${kpi('عمليات معلقة',x.pending,'عملية','alert','red',0)}
 </div>
 <div class="grid two-col"><div class="panel"><div class="panel-head"><h2>آخر العمليات المالية</h2><button class="ghost" data-icon="sync" id="dashRefresh">تحديث</button></div><div class="table-wrap">${x.recent.length?`<table><thead><tr><th>التاريخ</th><th>المرجع</th><th>البيان</th><th>المصدر</th></tr></thead><tbody>${x.recent.map(r=>`<tr><td class="nowrap">${dte(r.date)}</td><td class="mono">${esc(r.reference)}</td><td>${esc(r.description)}</td><td>${esc(r.source_type)}</td></tr>`).join('')}</tbody></table>`:empty('لا توجد عمليات بعد')}</div></div>
 <div class="panel"><div class="panel-head"><h2>اختصارات التشغيل</h2></div><div class="panel-body grid">${quickAction('مبيعات / POS','مسح باركود وتحرير فاتورة','sales','sales')}${quickAction('إضافة صنف','وحدات وأسعار وباركود','items','items','add-item')}${quickAction('عميل جديد','رصيد افتتاحي وكشف حساب','users','partners','add-customer')}${quickAction('التقارير','ميزان المراجعة والأرباح','reports','reports')}</div></div></div>`;
 $$('[data-route-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.routeGo));$('#dashRefresh').onclick=renderDashboard;$$('[data-quick]').forEach(b=>b.onclick=async()=>{await navigate(b.dataset.route);if(b.dataset.quick==='add-item')openItemModal();if(b.dataset.quick==='add-customer')openPartnerModal('Customer')});
}
function kpi(label,val,unit,ic,color,digits=2){return `<div class="kpi"><div class="kpi-top"><div><label>${label}</label><strong>${digits?fmt(val):Number(val).toLocaleString('en-US')}</strong><small>${unit}</small></div><span class="kpi-icon ${color}">${icon(ic)}</span></div></div>`}
function quickAction(title,sub,ic,route,quick=''){return `<button class="quick-card" data-route="${route}" data-quick="${quick}" style="display:grid;grid-template-columns:auto 1fr;gap:9px;text-align:right;color:var(--text);background:var(--surface2)"><span class="kpi-icon blue">${icon(ic)}</span><span><strong style="display:block">${title}</strong><small class="muted">${sub}</small></span></button>`}

async function renderItems(q=''){state.items=await api('/items?'+qs({q}));const rowsHtml=state.items.map(i=>`<tr><td><strong>${esc(i.name)}</strong><small class="muted" style="display:block">${esc(i.sku)}</small></td><td>${esc(i.base_unit_name)}</td><td>${i.units.map(u=>`<span class="status posted">${esc(u.unit_name)} × ${fmt3(u.factor)}</span>`).join(' ')}</td><td class="mono">${i.units.map(u=>esc(u.barcode)).join('<br>')}</td><td class="num">${fmt3(i.stock.quantity)}</td><td class="num">${fmt(i.stock.averageCost)}</td><td class="num">${fmt(i.stock.value)}</td><td><div class="row-actions actions"><button class="ghost icon-only" data-act="stock" data-id="${i.id}" data-icon="reports" title="كرت الصنف"></button><button class="ghost icon-only" data-act="edit" data-id="${i.id}" data-icon="edit" title="تعديل"></button><button class="danger icon-only" data-act="delete" data-id="${i.id}" data-icon="trash" title="حذف"></button></div></td></tr>`).join('');
 $('#view').innerHTML=pageHead('الأصناف والمخزون','إدارة الوحدات والباركود والأسعار والأرصدة الحية',`<button id="addItem" data-icon="plus">صنف جديد</button><button class="ghost" id="refreshItems" data-icon="sync">تحديث</button>`)+`<div class="panel"><div class="panel-head"><div class="searchbox">${icon('search')}<input id="itemFilter" placeholder="بحث بالاسم أو الكود أو الباركود"/></div><span class="muted">${state.items.length} صنف</span></div><div class="table-wrap"><table><thead><tr><th>الصنف</th><th>الأساسية</th><th>الوحدات</th><th>الباركود</th><th>الرصيد الأساسي</th><th>متوسط التكلفة</th><th>قيمة المخزون</th><th></th></tr></thead><tbody>${rowsHtml||''}</tbody></table>${rowsHtml?'':empty()}</div></div>`;
 $('#addItem').onclick=()=>openItemModal();$('#refreshItems').onclick=renderItems;$('#itemFilter').value=q;$('#itemFilter').oninput=e=>{const v=e.target.value;clearTimeout(window.__itemSearchTimer);window.__itemSearchTimer=setTimeout(()=>renderItems(v),160)};$$('[data-act]').forEach(b=>b.onclick=()=>{const it=state.items.find(x=>x.id===b.dataset.id); if(b.dataset.act==='edit')openItemModal(it);if(b.dataset.act==='stock')openStockCard(it);if(b.dataset.act==='delete')deleteItem(it)});
}
function unitRow(u={}){return `<div class="unit-row grid" style="grid-template-columns:1.2fr .7fr 1.1fr 1fr .7fr auto;gap:7px;align-items:end;margin-bottom:7px"><div class="field"><label>الوحدة</label><select class="u-unit">${opt(state.boot.units,'id','name',u.unit_id||u.unitId)}</select></div><div class="field"><label>المعامل</label><input class="u-factor num" type="number" step="0.001" min="0.001" value="${u.factor??1}"/></div><div class="field"><label>الباركود</label><input class="u-barcode mono" value="${esc(u.barcode||'')}"/></div><div class="field"><label>سعر البيع</label><input class="u-price num" type="number" step="0.01" value="${u.sales_price??u.salesPrice??0}"/></div><div class="field"><label>تكلفة افتتاحية</label><input class="u-cost num" type="number" step="0.01" value="${u.opening_cost??u.openingCost??0}"/></div><div class="actions"><label class="switch" title="الوحدة الأساسية"><input class="u-base" type="radio" name="baseUnit" ${u.is_base||u.isBase?'checked':''}/><span>أساسية</span></label><button type="button" class="ghost icon-only gen-u-barcode" data-icon="barcode" title="توليد باركود"></button><button type="button" class="danger icon-only del-unit" data-icon="trash" title="حذف الوحدة"></button></div></div>`}
function openItemModal(item=null){const accounts=postable(),invAcc=accountByCode('1140'),salesAcc=accountByCode('4100'),cogsAcc=accountByCode('5100');const units=item?.units?.length?item.units:[{unit_id:state.boot.units.find(u=>u.code==='EA')?.id||state.boot.units[0].id,factor:1,is_base:1}];const body=`<form id="itemForm"><div class="form-grid cols3"><div class="field"><label>كود الصنف SKU</label><input id="iSku" required value="${esc(item?.sku||'')}"/></div><div class="field"><label>اسم الصنف</label><input id="iName" required value="${esc(item?.name||'')}"/></div><div class="field"><label>حساب المخزون</label><select id="iInv">${opt(accounts,'id','name',item?.inventory_account_id||invAcc?.id)}</select></div><div class="field"><label>حساب المبيعات</label><select id="iSales">${opt(accounts,'id','name',item?.sales_account_id||salesAcc?.id)}</select></div><div class="field"><label>حساب COGS</label><select id="iCogs">${opt(accounts,'id','name',item?.cogs_account_id||cogsAcc?.id)}</select></div></div><div class="sep"></div><div class="panel-head" style="padding:0 0 10px;border:0"><h3>الوحدات والباركود والأسعار</h3><button type="button" class="ghost" id="addUnit" data-icon="plus">إضافة وحدة</button></div><div id="unitRows">${units.map(unitRow).join('')}</div></form>`;const m=modal(item?'تعديل الصنف':'إضافة صنف جديد',body,{wide:true,foot:`<button id="saveItem" data-icon="save">حفظ الصنف</button><button class="ghost modal-cancel" data-icon="close">إلغاء</button>`,onOpen:(root,close)=>{const bind=()=>{$$('.gen-u-barcode',root).forEach(b=>b.onclick=()=>run(async()=>{const x=await api('/barcode/generate',{method:'POST'});$('.u-barcode',b.closest('.unit-row')).value=x.barcode;toast('تم توليد الباركود',x.barcode)}));$$('.del-unit',root).forEach(b=>b.onclick=()=>{if($$('.unit-row',root).length<=1)return toast('تنبيه','يجب إبقاء وحدة واحدة على الأقل','error');b.closest('.unit-row').remove()});btnIconize(root)};bind();$('#addUnit',root).onclick=()=>{$('#unitRows',root).insertAdjacentHTML('beforeend',unitRow({}));bind()};$('.modal-cancel',root).onclick=close;$('#saveItem',root).onclick=()=>run(async()=>{const urows=$$('.unit-row',root).map(r=>({unitId:$('.u-unit',r).value,factor:+$('.u-factor',r).value,barcode:$('.u-barcode',r).value.trim(),salesPrice:+$('.u-price',r).value,openingCost:+$('.u-cost',r).value,isBase:$('.u-base',r).checked}));if(!urows.some(x=>x.isBase))throw new Error('حدد الوحدة الأساسية');if(urows.some(x=>!x.barcode))throw new Error('كل وحدة تحتاج باركود');const base=urows.find(x=>x.isBase);const payload={id:item?.id||null,sku:$('#iSku',root).value,name:$('#iName',root).value,baseUnitId:base.unitId,inventoryAccountId:$('#iInv',root).value,salesAccountId:$('#iSales',root).value,cogsAccountId:$('#iCogs',root).value,units:urows};await api('/items',{method:'POST',body:payload});toast('تم الحفظ','تم حفظ الصنف والوحدات والأسعار في SQLite');close();await renderItems()},{loading:true})}});return m}
async function deleteItem(it){if(!confirm(`حذف الصنف ${it.name}؟`))return;await run(async()=>{await api('/items/'+it.id,{method:'DELETE'});toast('تم الحذف',it.name);await renderItems()},{loading:true})}
async function openStockCard(it){const x=await run(()=>api('/stock-card/'+it.id));const body=`<div class="page-head"><div class="page-title"><h1 style="font-size:19px">${esc(it.name)}</h1><p>${esc(it.sku)} — الرصيد ${fmt3(x.position.quantity)} — متوسط ${fmt(x.position.averageCost)}</p></div><button id="printStock" data-icon="print">طباعة A4</button></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>المصدر</th><th>الكمية</th><th>القيمة</th><th>التكلفة</th><th>الرصيد</th></tr></thead><tbody>${x.rows.map(r=>`<tr><td>${dte(r.date)}</td><td>${esc(r.source_type)}</td><td class="num ${r.quantity_delta<0?'text-red':'text-green'}">${fmt3(r.quantity_delta)}</td><td class="num">${fmt(r.value_delta)}</td><td class="num">${fmt(r.unit_cost)}</td><td class="num">${fmt3(r.running_quantity)}</td></tr>`).join('')}</tbody></table></div>`;modal('كرت حركة الصنف',body,{wide:true,onOpen:root=>$('#printStock',root).onclick=()=>window.print()})}

async function renderPartners(q=''){state.partners=await api('/partners?'+qs({type:state.partnerType,q}));const isCus=state.partnerType==='Customer';$('#view').innerHTML=pageHead('العملاء والموردون','بيانات كاملة، أرصدة حية، كشوف حساب وسندات سريعة',`<button id="addPartner" data-icon="plus">${isCus?'عميل':'مورد'} جديد</button>`)+`<div class="tabs"><button class="tab ${isCus?'active':''}" data-ptype="Customer">العملاء</button><button class="tab ${!isCus?'active':''}" data-ptype="Supplier">الموردون</button></div><div class="panel"><div class="panel-head"><div class="searchbox">${icon('search')}<input id="partnerFilter" placeholder="بحث بالاسم أو الهاتف"/></div><span class="muted">${state.partners.length} سجل</span></div><div class="table-wrap"><table><thead><tr><th>الكود</th><th>الاسم</th><th>الهاتف / واتساب</th><th>المدينة</th><th>الحد الائتماني</th><th>الرصيد الحي</th><th></th></tr></thead><tbody>${state.partners.map(p=>`<tr><td class="mono">${esc(p.code)}</td><td><strong>${esc(p.name)}</strong><small class="muted" style="display:block">${esc(p.tax_number||'')}</small></td><td>${esc(p.phone)}<small class="muted" style="display:block">${esc(p.whatsapp)}</small></td><td>${esc(p.city)}</td><td class="num">${fmt(p.credit_limit)}</td><td class="num ${p.balance>0?'text-primary':''}">${fmt(p.balance)}</td><td><div class="row-actions actions"><button class="ghost icon-only" data-pa="statement" data-id="${p.id}" data-icon="reports" title="كشف الحساب"></button><button class="ghost icon-only" data-pa="voucher" data-id="${p.id}" data-icon="receipt" title="سند سريع"></button><button class="ghost icon-only" data-pa="edit" data-id="${p.id}" data-icon="edit"></button></div></td></tr>`).join('')}</tbody></table>${state.partners.length?'':empty()}</div></div>`;$$('[data-ptype]').forEach(b=>b.onclick=()=>{state.partnerType=b.dataset.ptype;renderPartners()});$('#addPartner').onclick=()=>openPartnerModal(state.partnerType);$('#partnerFilter').value=q;$('#partnerFilter').oninput=e=>{const v=e.target.value;clearTimeout(window.__partnerSearchTimer);window.__partnerSearchTimer=setTimeout(()=>renderPartners(v),160)};$$('[data-pa]').forEach(b=>b.onclick=()=>{const p=state.partners.find(x=>x.id===b.dataset.id);if(b.dataset.pa==='edit')openPartnerModal(p.type,p);if(b.dataset.pa==='statement')openPartnerStatement(p);if(b.dataset.pa==='voucher')openVoucherModal(p.type==='Customer'?'receipt':'payment',p)})}
function openPartnerModal(type='Customer',p=null){const body=`<form><div class="form-grid cols3"><div class="field"><label>الاسم</label><input id="pName" value="${esc(p?.name||'')}"/></div><div class="field"><label>الهاتف</label><input id="pPhone" value="${esc(p?.phone||'')}"/></div><div class="field"><label>واتساب</label><input id="pWhats" value="${esc(p?.whatsapp||'')}"/></div><div class="field"><label>المدينة</label><input id="pCity" value="${esc(p?.city||'')}"/></div><div class="field"><label>العنوان</label><input id="pAddr" value="${esc(p?.address||'')}"/></div><div class="field"><label>الرقم الضريبي</label><input id="pTax" value="${esc(p?.tax_number||'')}"/></div><div class="field"><label>الحد الائتماني</label><input id="pLimit" type="number" step="0.01" value="${p?.credit_limit||0}"/></div>${p?'':`<div class="field"><label>الرصيد الافتتاحي</label><input id="pOpening" type="number" step="0.01" value="0"/><span class="hint">يولد قيداً افتتاحياً متوازناً تلقائياً</span></div>`}</div></form>`;modal(`${p?'تعديل':'إضافة'} ${type==='Customer'?'عميل':'مورد'}`,body,{foot:`<button id="savePartner" data-icon="save">حفظ</button><button class="ghost modal-cancel" data-icon="close">إلغاء</button>`,onOpen:(root,close)=>{$('.modal-cancel',root).onclick=close;$('#savePartner',root).onclick=()=>run(async()=>{await api('/partners',{method:'POST',body:{id:p?.id||null,type,name:$('#pName',root).value,phone:$('#pPhone',root).value,whatsapp:$('#pWhats',root).value,city:$('#pCity',root).value,address:$('#pAddr',root).value,taxNumber:$('#pTax',root).value,creditLimit:+$('#pLimit',root).value,openingBalance:+($('#pOpening',root)?.value||0)}});toast('تم الحفظ',`${type==='Customer'?'العميل':'المورد'} محفوظ في SQLite`);close();if(state.route==='partners')await renderPartners();else if(state.route==='sales')await renderInvoice('sale');else if(state.route==='purchases')await renderInvoice('purchase')},{loading:true})}})}
async function openPartnerStatement(p){const x=await run(()=>api('/partners/'+p.id+'/statement'));const body=`<div class="toolbar" style="margin-bottom:10px"><div class="field"><label>من</label><input id="stFrom" type="date"/></div><div class="field"><label>إلى</label><input id="stTo" type="date"/></div><button id="stFilter" data-icon="search">تطبيق</button><button class="ghost" id="stPrint" data-icon="print">طباعة A4</button></div><div id="statementBody">${statementTable(x)}</div>`;modal('كشف حساب — '+esc(p.name),body,{wide:true,onOpen:(root)=>{$('#stFilter',root).onclick=()=>run(async()=>{$('#statementBody',root).innerHTML=statementTable(await api('/partners/'+p.id+'/statement?'+qs({fromDate:$('#stFrom',root).value,toDate:$('#stTo',root).value}))) });$('#stPrint',root).onclick=()=>window.print()}})}
function statementTable(x){return `<div class="kpi" style="margin-bottom:10px"><label>الرصيد الحالي</label><strong>${fmt(x.balance)}</strong></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>المرجع</th><th>البيان</th><th>مدين</th><th>دائن</th><th>الرصيد</th></tr></thead><tbody>${x.rows.map(r=>`<tr><td>${dte(r.date)}</td><td class="mono">${esc(r.reference)}</td><td>${esc(r.description)}</td><td class="num">${fmt(r.debit)}</td><td class="num">${fmt(r.credit)}</td><td class="num">${fmt(r.running_balance)}</td></tr>`).join('')}</tbody></table></div>`}

function newInvoiceState(kind){return {id:null,kind,warehouseId:state.boot.warehouses[0]?.id||'',settlementAccountId:cashAccounts()[0]?.id||'',partnerId:null,paymentMode:'cash',discount:0,taxRate:state.boot.settings.tax_enabled?state.boot.settings.tax_rate:0,notes:'',lines:[],status:'Draft'}}
async function renderInvoice(kind){if(!state.invoice[kind])state.invoice[kind]=newInvoiceState(kind);const ed=state.invoice[kind];const partnerType=kind==='sale'?'Customer':'Supplier';const [partners,docs,items]=await Promise.all([api('/partners?'+qs({type:partnerType})),api('/invoices?'+qs({kind})),api('/items')]);state.items=items;const title=kind==='sale'?'المبيعات ونقطة البيع':'المشتريات';const partnerLabel=kind==='sale'?'العميل':'المورد';$('#view').innerHTML=pageHead(title,kind==='sale'?'POS تفاعلي — باركود، مسودة، ترحيل، COGS ومخزون':'مشتريات — وحدات التحويل، WAC وذمم الموردين',`<button id="newInvoice" data-icon="plus">فاتورة جديدة <kbd>F2</kbd></button><button class="ghost" id="invoicePrint80" data-icon="print">80mm <kbd>F8</kbd></button><button class="ghost" id="invoicePrintA4" data-icon="print">A4</button>`)+`<div class="invoice-layout"><div class="invoice-main"><div class="panel"><div class="panel-body"><div class="form-grid cols3"><div class="field"><label>المستودع</label><select id="invWarehouse">${opt(state.boot.warehouses,'id','name',ed.warehouseId)}</select></div><div class="field"><label>طريقة الدفع</label><select id="invPayment"><option value="cash" ${ed.paymentMode==='cash'?'selected':''}>نقدي — صندوق/بنك</option><option value="credit" ${ed.paymentMode==='credit'?'selected':''}>آجل — ذمة ${partnerLabel}</option></select></div><div class="field"><label>${partnerLabel}</label><div style="display:flex;gap:5px"><select id="invPartner" style="flex:1"><option value="">— بدون —</option>${opt(partners,'id','name',ed.partnerId)}</select><button class="ghost icon-only" id="quickPartner" data-icon="plus" title="إضافة ${partnerLabel}"></button></div></div><div class="field"><label>حساب التسوية</label><select id="invSettlement">${opt(cashAccounts(),'id','name',ed.paymentMode==='cash'?ed.settlementAccountId:cashAccounts()[0]?.id)}</select><span class="hint" id="settlementHint">${ed.paymentMode==='cash'?'صندوق أو بنك':'يُستخدم حساب ذمة الطرف تلقائياً'}</span></div></div><div class="sep"></div><div class="scan-row"><div class="scan-input field"><label>قارئ الباركود — Enter</label><span class="scan-symbol">${icon('barcode')}</span><input id="barcodeInput" class="mono" placeholder="امسح باركود الحبة أو الكرتون ثم Enter"/></div><div class="scan-input field"><label>بحث تفاعلي عن الصنف</label><span class="scan-symbol">${icon('search')}</span><input id="itemSearch" placeholder="اكتب أي حرف..."/><div id="itemAutocomplete" class="autocomplete hidden"></div></div><button id="focusBarcode" class="ghost" data-icon="barcode">تركيز الباركود</button></div><div class="table-wrap"><table class="invoice-table"><thead><tr><th>#</th><th>الصنف</th><th>الوحدة</th><th>الكمية</th><th>السعر</th><th>الخصم</th><th>الإجمالي</th><th></th></tr></thead><tbody id="invoiceLines">${invoiceLinesHtml(ed)}</tbody></table></div></div></div></div><aside class="invoice-side"><div class="panel"><div class="panel-head"><h3>الإجماليات</h3><span class="status ${ed.status.toLowerCase()}">${ed.status}</span></div><div class="panel-body totals">${invoiceTotalsHtml(ed)}<div class="field"><label>خصم الفاتورة</label><input id="invoiceDiscount" type="number" step="0.01" value="${ed.discount||0}"/></div><div class="field"><label>الضريبة %</label><input id="invoiceTax" type="number" step="0.01" value="${ed.taxRate||0}"/></div><div class="field"><label>ملاحظات</label><textarea id="invoiceNotes">${esc(ed.notes||'')}</textarea></div><button id="saveDraft" class="warning" data-icon="save">حفظ كمسودة</button><button id="postInvoice" class="success" data-icon="check">حفظ وترحيل <kbd>F5</kbd></button></div></div><div class="quick-card"><h4>الفواتير السابقة</h4><div class="quick-list">${docs.slice(0,8).map(d=>`<div class="quick-doc"><div><strong>${esc(d.number)} — ${fmt(d.total)}</strong><small>${dte(d.date)} · ${esc(d.partner_name||'نقدي')}</small></div><div class="actions">${d.status==='Draft'?`<button class="ghost icon-only doc-edit" data-id="${d.id}" data-icon="edit" title="فتح المسودة"></button>`:''}${d.status==='Posted'?`<button class="danger icon-only doc-reverse" data-id="${d.id}" data-icon="reverse" title="عكس"></button>`:''}<button class="ghost icon-only doc-print" data-id="${d.id}" data-icon="print"></button></div></div>`).join('')||'<span class="muted">لا توجد فواتير</span>'}</div></div></aside></div>`;wireInvoice(kind,partners,docs)}
function calcInvoice(ed){let subtotal=ed.lines.reduce((s,l)=>s+l.quantity*l.unitPrice-l.discount,0)-Number(ed.discount||0);subtotal=Math.max(0,subtotal);const tax=subtotal*Number(ed.taxRate||0)/100;return{subtotal,tax,total:subtotal+tax}}
function invoiceTotalsHtml(ed){const t=calcInvoice(ed);return `<div class="total-row"><span>قبل الضريبة</span><strong>${fmt(t.subtotal)}</strong></div><div class="total-row"><span>الضريبة</span><strong>${fmt(t.tax)}</strong></div><div class="total-row grand"><span>الصافي</span><strong>${fmt(t.total)}</strong></div>`}
function invoiceLinesHtml(ed){return ed.lines.map((l,i)=>{const it=state.items.find(x=>x.id===l.itemId);return `<tr data-line="${i}"><td>${i+1}</td><td><strong>${esc(it?.name||l.itemName||'')}</strong><small class="muted" style="display:block">${esc(it?.sku||'')}</small></td><td><select class="table-input l-unit">${(it?.units||[]).map(u=>`<option value="${u.id}" ${u.id===l.itemUnitId?'selected':''}>${esc(u.unit_name)} × ${fmt3(u.factor)}</option>`).join('')}</select></td><td><div class="qty-control"><button class="l-minus">−</button><input class="table-input l-qty num" type="number" step="0.001" value="${l.quantity}"/><button class="l-plus">+</button></div></td><td><input class="table-input l-price num" type="number" step="0.01" value="${l.unitPrice}"/></td><td><input class="table-input l-disc num" type="number" step="0.01" value="${l.discount||0}"/></td><td class="num l-total"><strong>${fmt(l.quantity*l.unitPrice-l.discount)}</strong></td><td><button class="danger icon-only l-remove" data-icon="trash"></button></td></tr>`}).join('')||`<tr><td colspan="8">${empty('ابدأ بمسح باركود أو البحث عن صنف')}</td></tr>`}
function wireInvoice(kind,partners,docs){const ed=state.invoice[kind];const refreshLines=()=>{const tb=$('#invoiceLines');tb.innerHTML=invoiceLinesHtml(ed);btnIconize(tb);wireLines();$('.totals').firstElementChild?.parentElement;const t=calcInvoice(ed);const rows=$$('.total-row');if(rows[0])rows[0].querySelector('strong').textContent=fmt(t.subtotal);if(rows[1])rows[1].querySelector('strong').textContent=fmt(t.tax);if(rows[2])rows[2].querySelector('strong').textContent=fmt(t.total)};const wireLines=()=>{$$('[data-line]').forEach(tr=>{const i=+tr.dataset.line,l=ed.lines[i],it=state.items.find(x=>x.id===l.itemId);$('.l-unit',tr).onchange=e=>{const u=it.units.find(x=>x.id===e.target.value);l.itemUnitId=u.id;l.unitPrice=Number(u.sales_price||0);refreshLines()};$('.l-qty',tr).oninput=e=>{l.quantity=Math.max(0,+e.target.value);refreshLines()};$('.l-price',tr).oninput=e=>{l.unitPrice=Math.max(0,+e.target.value);refreshLines()};$('.l-disc',tr).oninput=e=>{l.discount=Math.max(0,+e.target.value);refreshLines()};$('.l-minus',tr).onclick=()=>{l.quantity=Math.max(.001,l.quantity-1);refreshLines()};$('.l-plus',tr).onclick=()=>{l.quantity+=1;refreshLines()};$('.l-remove',tr).onclick=()=>{ed.lines.splice(i,1);refreshLines()}})};wireLines();
 const add=(it,u,qty=1)=>{const ex=ed.lines.find(x=>x.itemUnitId===u.id);if(ex)ex.quantity+=qty;else ed.lines.push({itemId:it.id,itemUnitId:u.id,quantity:qty,unitPrice:Number(u.sales_price||0),discount:0,itemName:it.name});refreshLines();toast('تمت إضافة الصنف',`${it.name} — ${u.unit_name}`)};
 $('#barcodeInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const v=e.target.value.trim();if(!v)return;run(async()=>{const x=await api('/items/scan/'+encodeURIComponent(v));const it=state.items.find(z=>z.id===x.item_id)||{id:x.item_id,name:x.name,sku:x.sku,units:[]};let u=it.units.find(z=>z.id===x.item_unit_id);if(!u){u={id:x.item_unit_id,unit_name:x.unit_name,factor:x.factor,sales_price:x.sales_price,barcode:x.barcode};it.units.push(u)}add(it,u);e.target.value='';e.target.focus()})}};$('#focusBarcode').onclick=()=>$('#barcodeInput').focus();
 const ac=$('#itemAutocomplete');$('#itemSearch').oninput=e=>{const q=e.target.value.trim().toLowerCase();if(!q){ac.classList.add('hidden');return}const found=state.items.filter(i=>i.name.toLowerCase().includes(q)||i.sku.toLowerCase().includes(q)||i.units.some(u=>u.barcode.includes(q))).slice(0,12);ac.innerHTML=found.map(i=>`<div class="ac-item" data-i="${i.id}"><span><strong>${esc(i.name)}</strong><small>${esc(i.sku)} · رصيد ${fmt3(i.stock.quantity)}</small></span><span class="text-primary">${fmt(i.units[0]?.sales_price||0)}</span></div>`).join('');ac.classList.toggle('hidden',!found.length);$$('[data-i]',ac).forEach(x=>x.onclick=()=>{const it=state.items.find(z=>z.id===x.dataset.i);add(it,it.units.find(u=>u.is_base)||it.units[0]);ac.classList.add('hidden');$('#itemSearch').value=''})};
 $('#invWarehouse').onchange=e=>ed.warehouseId=e.target.value;$('#invPartner').onchange=e=>{ed.partnerId=e.target.value||null;syncSettlement()};$('#invPayment').onchange=e=>{ed.paymentMode=e.target.value;syncSettlement()};$('#invSettlement').onchange=e=>{if(ed.paymentMode==='cash')ed.settlementAccountId=e.target.value};function syncSettlement(){const sel=$('#invSettlement'),hint=$('#settlementHint');if(ed.paymentMode==='credit'){const p=partners.find(x=>x.id===ed.partnerId);if(!p){hint.textContent=`اختر ${kind==='sale'?'عميلاً':'مورداً'} لتحديد حساب الذمة`;sel.disabled=true;return}ed.settlementAccountId=p.control_account_id;sel.disabled=true;hint.textContent='حساب الذمة: '+(state.boot.accounts.find(a=>a.id===p.control_account_id)?.name||'ذمة الطرف')}else{sel.disabled=false;if(!cashAccounts().some(a=>a.id===ed.settlementAccountId))ed.settlementAccountId=sel.value||cashAccounts()[0]?.id;sel.value=ed.settlementAccountId;hint.textContent='صندوق أو بنك'}}syncSettlement();
 $('#invoiceDiscount').oninput=e=>{ed.discount=+e.target.value;refreshLines()};$('#invoiceTax').oninput=e=>{ed.taxRate=+e.target.value;refreshLines()};$('#invoiceNotes').oninput=e=>ed.notes=e.target.value;$('#quickPartner').onclick=()=>openPartnerModal(kind==='sale'?'Customer':'Supplier');$('#newInvoice').onclick=()=>{state.invoice[kind]=newInvoiceState(kind);renderInvoice(kind)};
 const payload=()=>({id:ed.id,kind,warehouseId:ed.warehouseId,settlementAccountId:ed.settlementAccountId,partnerId:ed.partnerId,paymentMode:ed.paymentMode,discount:ed.discount,taxRate:ed.taxRate,notes:ed.notes,lines:ed.lines.map(({itemId,itemUnitId,quantity,unitPrice,discount})=>({itemId,itemUnitId,quantity,unitPrice,discount}))});
 $('#saveDraft').onclick=()=>run(async()=>{if(ed.paymentMode==='credit'&&!ed.partnerId)throw new Error('الفاتورة الآجلة تتطلب اختيار الطرف');const x=await api('/invoices/draft',{method:'POST',body:payload()});ed.id=x.id;ed.status='Draft';toast('تم حفظ المسودة','يمكن فتحها وتعديلها لاحقاً');await renderInvoice(kind)},{loading:true});$('#postInvoice').onclick=()=>run(async()=>{if(ed.paymentMode==='credit'&&!ed.partnerId)throw new Error('الفاتورة الآجلة تتطلب اختيار الطرف');const x=await api('/invoices/post',{method:'POST',body:payload()});ed.id=x.id;ed.status='Posted';toast('تم الترحيل',`تم ترحيل ${x.number} وتحديث المخزون والقيود`);state.invoice[kind]=newInvoiceState(kind);await renderInvoice(kind)},{loading:true});
 $$('.doc-edit').forEach(b=>b.onclick=()=>{const d=docs.find(x=>x.id===b.dataset.id);state.invoice[kind]={id:d.id,kind,warehouseId:d.warehouse_id,settlementAccountId:d.settlement_account_id,partnerId:d.partner_id,paymentMode:d.payment_mode,discount:d.discount,taxRate:d.tax_rate,notes:d.notes,status:d.status,lines:d.lines.map(l=>({itemId:l.item_id,itemUnitId:l.item_unit_id,quantity:l.quantity,unitPrice:l.unit_price,discount:l.discount,itemName:l.item_name}))};renderInvoice(kind);toast('تم فتح المسودة','يمكن تعديل الكميات والأسعار والوحدات ثم إعادة الحفظ')});$$('.doc-reverse').forEach(b=>b.onclick=()=>{if(confirm('إنشاء عكس محاسبي ومخزني للفاتورة؟'))run(async()=>{await api('/invoices/'+b.dataset.id+'/reverse',{method:'POST'});toast('تم العكس','تم إنشاء قيود وحركات مخزون عكسية');await renderInvoice(kind)},{loading:true})});$$('.doc-print').forEach(b=>b.onclick=()=>openInvoicePrint(b.dataset.id,'a4'));
 $('#invoicePrint80').onclick=()=>ensureInvoicePrint('thermal');$('#invoicePrintA4').onclick=()=>ensureInvoicePrint('a4');async function ensureInvoicePrint(size){if(!ed.id){const x=await api('/invoices/draft',{method:'POST',body:payload()});ed.id=x.id}openInvoicePrint(ed.id,size)}
}

async function renderVouchers(){const vs=await api('/vouchers');$('#view').innerHTML=pageHead('سندات القبض والصرف','مسودات، ترحيل، طباعة وعكس محاسبي',`<button id="newReceipt" data-icon="plus">سند قبض</button><button id="newPayment" class="ghost" data-icon="plus">سند صرف</button>`)+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>النوع</th><th>الرقم</th><th>التاريخ</th><th>الطرف</th><th>الحساب النقدي</th><th>المبلغ</th><th>الحالة</th><th></th></tr></thead><tbody>${vs.map(v=>`<tr><td>${v.kind==='receipt'?'قبض':'صرف'}</td><td class="mono">${esc(v.number)}</td><td>${dte(v.date)}</td><td>${esc(v.partner_name||'-')}</td><td>${esc(v.cash_name)}</td><td class="num">${fmt(v.amount)}</td><td><span class="status ${v.status.toLowerCase()}">${v.status}</span></td><td><div class="row-actions actions">${v.status==='Draft'?`<button class="ghost icon-only v-edit" data-id="${v.id}" data-icon="edit"></button>`:''}<button class="ghost icon-only v-print" data-id="${v.id}" data-icon="print"></button>${v.status==='Posted'?`<button class="danger icon-only v-rev" data-id="${v.id}" data-icon="reverse"></button>`:''}</div></td></tr>`).join('')}</tbody></table>${vs.length?'':empty()}</div></div>`;$('#newReceipt').onclick=()=>openVoucherModal('receipt');$('#newPayment').onclick=()=>openVoucherModal('payment');$$('.v-edit').forEach(b=>openAction(b,()=>openVoucherModal(vs.find(v=>v.id===b.dataset.id).kind,null,vs.find(v=>v.id===b.dataset.id))));$$('.v-print').forEach(b=>openAction(b,()=>openVoucherPrint(b.dataset.id,'a4')));$$('.v-rev').forEach(b=>openAction(b,()=>{if(confirm('عكس السند؟'))run(async()=>{await api('/vouchers/'+b.dataset.id+'/reverse',{method:'POST'});toast('تم عكس السند');renderVouchers()},{loading:true})}))}
function openAction(el,fn){el.onclick=fn}
async function openVoucherModal(kind,p=null,v=null){const type=kind==='receipt'?'Customer':'Supplier';const partners=await api('/partners?'+qs({type}));const cash=cashAccounts();const chosen=p||partners.find(x=>x.id===v?.partner_id);const counter=chosen?.control_account_id||v?.counter_account_id||(type==='Customer'?accountByCode('1130')?.id:accountByCode('2110')?.id);const body=`<div class="form-grid"><div class="field"><label>الطرف</label><select id="vPartner"><option value="">— بدون —</option>${opt(partners,'id','name',chosen?.id)}</select></div><div class="field"><label>الصندوق / البنك</label><select id="vCash">${opt(cash,'id','name',v?.cash_account_id||cash[0]?.id)}</select></div><div class="field"><label>الحساب المقابل</label><select id="vCounter">${opt(postable(),'id','name',counter)}</select></div><div class="field"><label>المبلغ</label><input id="vAmount" type="number" step="0.01" value="${v?.amount||''}"/></div><div class="field" style="grid-column:1/-1"><label>البيان</label><input id="vDesc" value="${esc(v?.description||'')}"/></div></div>`;modal(`${kind==='receipt'?'سند قبض':'سند صرف'} ${v?'— تعديل مسودة':''}`,body,{foot:`<button id="vPost" class="success" data-icon="check">ترحيل</button><button id="vDraft" class="warning" data-icon="save">حفظ مسودة</button><button class="ghost modal-cancel" data-icon="close">إلغاء</button>`,onOpen:(root,close)=>{const payload=draft=>({id:v?.id||null,kind,cashAccountId:$('#vCash',root).value,counterAccountId:$('#vCounter',root).value,partnerId:$('#vPartner',root).value||null,amount:+$('#vAmount',root).value,description:$('#vDesc',root).value,draft});$('#vPartner',root).onchange=e=>{const pp=partners.find(x=>x.id===e.target.value);if(pp)$('#vCounter',root).value=pp.control_account_id};$('#vPost',root).onclick=()=>run(async()=>{await api('/vouchers',{method:'POST',body:payload(false)});toast('تم ترحيل السند','تم تحديث الأرصدة وكشف الحساب');close();if(state.route==='vouchers')renderVouchers()},{loading:true});$('#vDraft',root).onclick=()=>run(async()=>{await api('/vouchers',{method:'POST',body:payload(true)});toast('تم حفظ مسودة السند');close();if(state.route==='vouchers')renderVouchers()},{loading:true});$('.modal-cancel',root).onclick=close}})}

async function renderAccounts(){const [tb,js]=await Promise.all([api('/reports/trial-balance'),api('/journals')]);const accounts=state.boot.accounts;$('#view').innerHTML=pageHead('شجرة الحسابات والقيود','أرصدة حية ومحرر قيد يومية متعدد الأسطر',`<button id="addAccount" data-icon="plus">حساب فرعي</button><button id="newJournal" class="ghost" data-icon="plus">قيد يومية</button>`)+`<div class="grid two-col"><div class="panel"><div class="panel-head"><h2>شجرة الحسابات</h2><span class="muted">${accounts.length} حساب</span></div><div class="table-wrap"><table><thead><tr><th>الكود</th><th>الحساب</th><th>النوع</th><th>الطبيعة</th><th>الرصيد</th><th></th></tr></thead><tbody>${accounts.map(a=>{const b=tb.find(x=>x.id===a.id);return `<tr><td class="mono">${a.code}</td><td style="padding-right:${10+(a.parent_id?14:0)}px">${esc(a.name)}</td><td>${a.type}</td><td>${a.normal}</td><td class="num">${fmt(b?.balance||0)}</td><td><button class="ghost icon-only acc-edit" data-id="${a.id}" data-icon="edit"></button></td></tr>`}).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><h2>آخر القيود</h2></div><div class="quick-list panel-body">${js.slice(0,12).map(j=>`<div class="quick-doc"><div><strong>${esc(j.reference)} — ${esc(j.description)}</strong><small>${dte(j.date)} · ${esc(j.source_type)}</small></div><div class="actions"><button class="ghost icon-only j-view" data-id="${j.id}" data-icon="eye"></button><button class="danger icon-only j-rev" data-id="${j.id}" data-icon="reverse"></button></div></div>`).join('')}</div></div></div>`;$('#addAccount').onclick=()=>openAccountModal();$('#newJournal').onclick=()=>openJournalModal();$$('.acc-edit').forEach(b=>b.onclick=()=>openAccountModal(accounts.find(a=>a.id===b.dataset.id)));$$('.j-view').forEach(b=>b.onclick=()=>openJournalView(js.find(j=>j.id===b.dataset.id)));$$('.j-rev').forEach(b=>b.onclick=()=>{if(confirm('إنشاء قيد عكسي؟'))run(async()=>{await api('/journals/'+b.dataset.id+'/reverse',{method:'POST'});toast('تم إنشاء القيد العكسي');renderAccounts()},{loading:true})})}
function openAccountModal(a=null){const body=`<div class="form-grid"><div class="field"><label>الحساب الأب</label><select id="aParent"><option value="">— رئيسي —</option>${opt(state.boot.accounts.filter(x=>!x.postable),'id','name',a?.parent_id)}</select></div><div class="field"><label>الكود</label><input id="aCode" value="${esc(a?.code||'')}"/></div><div class="field"><label>الاسم</label><input id="aName" value="${esc(a?.name||'')}"/></div><div class="field"><label>النوع</label><select id="aType">${['Asset','Liability','Equity','Revenue','Expense'].map(x=>`<option ${x===a?.type?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>الطبيعة</label><select id="aNormal"><option ${a?.normal==='Debit'?'selected':''}>Debit</option><option ${a?.normal==='Credit'?'selected':''}>Credit</option></select></div><label class="switch"><input id="aPostable" type="checkbox" ${a?.postable!==0?'checked':''}/>قابل للترحيل</label></div>`;modal(a?'تعديل الحساب':'إضافة حساب فرعي',body,{foot:`<button id="aSave" data-icon="save">حفظ</button>`,onOpen:(root,close)=>$('#aSave',root).onclick=()=>run(async()=>{await api('/accounts',{method:'POST',body:{id:a?.id||null,code:$('#aCode',root).value,name:$('#aName',root).value,type:$('#aType',root).value,normal:$('#aNormal',root).value,parentId:$('#aParent',root).value||null,postable:$('#aPostable',root).checked}});toast('تم حفظ الحساب');close();await loadBoot();renderAccounts()},{loading:true})})}
function journalLineRow(v={}){return `<div class="j-line grid" style="grid-template-columns:2fr 1fr 1fr 2fr auto;gap:7px;margin-bottom:6px"><select class="jl-account table-input">${opt(postable(),'id','name',v.account_id)}</select><input class="jl-debit table-input num" type="number" step="0.01" placeholder="مدين" value="${v.debit||''}"/><input class="jl-credit table-input num" type="number" step="0.01" placeholder="دائن" value="${v.credit||''}"/><input class="jl-memo table-input" placeholder="بيان السطر" value="${esc(v.memo||'')}"/><button class="danger icon-only jl-del" data-icon="trash"></button></div>`}
function openJournalModal(){const body=`<div class="form-grid"><div class="field"><label>المرجع</label><input id="jRef"/></div><div class="field"><label>البيان</label><input id="jDesc"/></div></div><div class="sep"></div><div id="jLines">${journalLineRow()}${journalLineRow()}</div><div class="toolbar"><button class="ghost" id="jAdd" data-icon="plus">إضافة سطر</button><div id="jBalance" class="balance-indicator bad">غير متوازن</div></div>`;modal('قيد يومية جديد',body,{wide:true,foot:`<button id="jPost" class="success" data-icon="check">ترحيل القيد</button>`,onOpen:(root,close)=>{const wire=()=>{$$('.jl-del',root).forEach(b=>b.onclick=()=>{if($$('.j-line',root).length>2)b.closest('.j-line').remove();recalc()});$$('.jl-debit,.jl-credit',root).forEach(i=>i.oninput=recalc);btnIconize(root)};const recalc=()=>{const debit=$$('.jl-debit',root).reduce((s,x)=>s+(+x.value||0),0),credit=$$('.jl-credit',root).reduce((s,x)=>s+(+x.value||0),0),ok=debit>0&&Math.abs(debit-credit)<.005;const el=$('#jBalance',root);el.className='balance-indicator '+(ok?'ok':'bad');el.textContent=ok?`متوازن ✓ — مدين ${fmt(debit)} = دائن ${fmt(credit)}`:`غير متوازن — مدين ${fmt(debit)} | دائن ${fmt(credit)} | الفرق ${fmt(Math.abs(debit-credit))}`};wire();$('#jAdd',root).onclick=()=>{$('#jLines',root).insertAdjacentHTML('beforeend',journalLineRow());wire()};$('#jPost',root).onclick=()=>run(async()=>{const lines=$$('.j-line',root).map(r=>({accountId:$('.jl-account',r).value,debit:+$('.jl-debit',r).value||0,credit:+$('.jl-credit',r).value||0,memo:$('.jl-memo',r).value})).filter(x=>x.debit||x.credit);await api('/journals',{method:'POST',body:{reference:$('#jRef',root).value,description:$('#jDesc',root).value,lines}});toast('تم ترحيل القيد');close();renderAccounts()},{loading:true});recalc()}})}
function openJournalView(j){modal('تفاصيل القيد',`<div class="kpi" style="margin-bottom:10px"><strong>${esc(j.reference)}</strong><p>${esc(j.description)}</p><small>${dte(j.date)}</small></div><div class="table-wrap"><table><thead><tr><th>الحساب</th><th>البيان</th><th>مدين</th><th>دائن</th></tr></thead><tbody>${j.lines.map(x=>`<tr><td>${esc(x.account_code)} — ${esc(x.account_name)}</td><td>${esc(x.memo)}</td><td class="num">${fmt(x.debit)}</td><td class="num">${fmt(x.credit)}</td></tr>`).join('')}</tbody></table></div>`,{wide:true})}

async function renderReports(){
 const [tb,pl,inv,integ,sync]=await Promise.all([api('/reports/trial-balance'),api('/reports/profit-loss'),api('/reports/inventory'),api('/reports/integrity'),api('/sync')]);
 $('#view').innerHTML=pageHead('التقارير والنسخ الاحتياطي والمزامنة','تقارير محاسبية مباشرة من SQLite مع أدوات صيانة آمنة')+`
 <div class="grid three-col">
  <div class="kpi"><label>الإيرادات</label><strong class="text-green">${fmt(pl.revenue)}</strong></div>
  <div class="kpi"><label>المصروفات</label><strong class="text-red">${fmt(pl.expense)}</strong></div>
  <div class="kpi"><label>صافي الربح</label><strong class="${pl.profit>=0?'text-green':'text-red'}">${fmt(pl.profit)}</strong></div>
 </div>
 <div class="tabs" style="margin-top:14px">
  <button class="tab active" data-rpt="trial">ميزان المراجعة</button>
  <button class="tab" data-rpt="pnl">الأرباح والخسائر</button>
  <button class="tab" data-rpt="inventory">جرد المخزون</button>
  <button class="tab" data-rpt="statement">كشف حساب</button>
  <button class="tab" data-rpt="maintenance">الصيانة والمزامنة</button>
 </div><div id="reportPanel" class="panel"></div>`;

 const show=async name=>{
  $$('[data-rpt]').forEach(b=>b.classList.toggle('active',b.dataset.rpt===name));
  const p=$('#reportPanel');
  if(name==='trial'){
   p.innerHTML=`<div class="panel-head"><h2>ميزان المراجعة</h2><button class="ghost" onclick="window.print()" data-icon="print">طباعة A4</button></div><div class="table-wrap"><table><thead><tr><th>الكود</th><th>الحساب</th><th>مدين</th><th>دائن</th><th>الرصيد</th></tr></thead><tbody>${tb.map(x=>`<tr><td class="mono">${x.code}</td><td>${esc(x.name)}</td><td class="num">${fmt(x.debit)}</td><td class="num">${fmt(x.credit)}</td><td class="num">${fmt(x.balance)}</td></tr>`).join('')}</tbody></table></div>`;
  }
  if(name==='pnl'){
   const rowsPnl=tb.filter(x=>x.type==='Revenue'||x.type==='Expense');
   p.innerHTML=`<div class="panel-head"><div><h2>قائمة الأرباح والخسائر</h2><p class="muted">القيم من القيود المرحلة مباشرة</p></div><button class="ghost" onclick="window.print()" data-icon="print">طباعة A4</button></div><div class="panel-body"><div class="grid three-col"><div class="kpi"><label>الإيرادات</label><strong class="text-green">${fmt(pl.revenue)}</strong></div><div class="kpi"><label>المصروفات</label><strong class="text-red">${fmt(pl.expense)}</strong></div><div class="kpi"><label>صافي الربح</label><strong class="${pl.profit>=0?'text-green':'text-red'}">${fmt(pl.profit)}</strong></div></div></div><div class="table-wrap"><table><thead><tr><th>الكود</th><th>الحساب</th><th>النوع</th><th>الرصيد</th></tr></thead><tbody>${rowsPnl.map(x=>`<tr><td class="mono">${x.code}</td><td>${esc(x.name)}</td><td>${x.type==='Revenue'?'إيراد':'مصروف'}</td><td class="num">${fmt(x.type==='Revenue'?-x.balance:x.balance)}</td></tr>`).join('')}</tbody></table></div>`;
  }
  if(name==='inventory'){
   p.innerHTML=`<div class="panel-head"><h2>جرد المخزون</h2><button class="ghost" onclick="window.print()" data-icon="print">طباعة</button></div><div class="table-wrap"><table><thead><tr><th>الصنف</th><th>الرصيد الأساسي</th><th>متوسط التكلفة</th><th>القيمة</th><th>الوحدات</th></tr></thead><tbody>${inv.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small class="muted mono">${esc(x.sku)}</small></td><td class="num">${fmt3(x.stock.quantity)}</td><td class="num">${fmt(x.stock.averageCost)}</td><td class="num">${fmt(x.stock.value)}</td><td>${x.units.map(u=>`${esc(u.unit_name)} = ${fmt3(u.factor)}`).join(' · ')}</td></tr>`).join('')}</tbody></table></div>`;
  }
  if(name==='statement'){
   p.innerHTML=`<div class="panel-body"><div class="form-grid cols3"><div class="field"><label>نوع الكشف</label><select id="rStatementType"><option value="partner">عميل / مورد</option><option value="account">حساب عام</option></select></div><div class="field"><label>الطرف / الحساب</label><select id="rEntity"></select></div><div></div><div class="field"><label>من</label><input id="rFrom" type="date"/></div><div class="field"><label>إلى</label><input id="rTo" type="date"/></div><div class="actions" style="align-items:end"><button id="rStatement" data-icon="search">عرض الكشف</button><button class="ghost" id="rStatementPrint" data-icon="print">طباعة A4</button></div></div><div id="rStatementBody"></div></div>`;
   const ps=await api('/partners');
   const fillEntities=()=>{const type=$('#rStatementType').value;$('#rEntity').innerHTML=type==='partner'?opt(ps,'id','name'):opt(state.boot.accounts.filter(a=>a.postable&&a.active),'id','name')};
   fillEntities();$('#rStatementType').onchange=fillEntities;
   const loadStatement=async()=>{const id=$('#rEntity').value;if(!id)throw new Error('اختر طرفاً أو حساباً');const path=$('#rStatementType').value==='partner'?`/partners/${id}/statement`:`/accounts/${id}/ledger`;const x=await api(path+'?'+qs({fromDate:$('#rFrom').value,toDate:$('#rTo').value}));$('#rStatementBody').innerHTML=statementTable(x);return x};
   $('#rStatement').onclick=()=>run(loadStatement,{loading:true});
   $('#rStatementPrint').onclick=()=>run(async()=>{await loadStatement();window.print()});
  }
  if(name==='maintenance'){
   const conflicts=sync.conflicts||[];
   p.innerHTML=`<div class="panel-body grid two-col"><div><h3>النسخ الاحتياطي وسلامة الدفاتر</h3><p class="muted">QuickCheck: <strong class="${integ.healthy?'text-green':'text-red'}">${esc(integ.quickCheck)}</strong> — تعارضات FK: ${integ.foreignKeys.length} — قيود غير متوازنة: ${integ.unbalanced.length}</p><div class="actions"><button id="backupNow" data-icon="download">نسخة احتياطية الآن</button><button class="ghost" id="integrityNow" data-icon="shield">فحص السلامة</button></div><div class="field" style="margin-top:14px"><label>مسار نسخة للاستعادة</label><input id="restorePath" class="mono" placeholder="/path/Qodynex-Backup.db"/></div><button class="danger" id="restoreNow" data-icon="upload">استعادة النسخة المحددة</button><div id="backupResult" class="muted" style="margin-top:10px"></div></div><div><h3>المزامنة والخادم</h3><div class="field"><label>Server URL</label><input id="serverUrl" class="mono" value="${esc(sync.serverUrl||'')}" placeholder="https://..."/></div><button id="saveServer" class="ghost" data-icon="save" style="margin-top:8px">حفظ الرابط</button><h4 style="margin-top:18px">تعارضات المزامنة</h4><div id="conflicts">${conflicts.length?conflicts.map(x=>`<div class="list-row"><div><strong>${esc(x.code)}</strong><small>${esc(x.message)}</small></div>${x.resolved?'<span class="badge success">محلول</span>':`<button class="ghost resolve-conflict" data-id="${x.id}" data-icon="check">تعليم كمحلول</button>`}</div>`).join(''):'<p class="muted">لا توجد تعارضات.</p>'}</div></div></div>`;
   $('#backupNow').onclick=()=>run(async()=>{const x=await api('/backup',{method:'POST'});$('#backupResult').textContent=`تم إنشاء: ${x.path} (${x.size.toLocaleString('en-US')} bytes)`;$('#restorePath').value=x.path;toast('تم إنشاء النسخة الاحتياطية',x.path)},{loading:true});
   $('#restoreNow').onclick=()=>run(async()=>{const path=$('#restorePath').value.trim();if(!path)throw new Error('أدخل مسار النسخة المراد استعادتها');await api('/restore',{method:'POST',body:{path}});toast('تمت استعادة النسخة','تم التحقق من SQLite واستعادة البيانات بنجاح');await loadBoot()},{loading:true});
   $('#integrityNow').onclick=()=>run(async()=>{const x=await api('/reports/integrity');toast(x.healthy?'سلامة الدفاتر مؤكدة':'يوجد خلل',x.healthy?'SQLite + FK + توازن القيود: سليم':JSON.stringify(x),x.healthy?'success':'error')});
   $('#saveServer').onclick=()=>run(async()=>{await api('/sync/settings',{method:'POST',body:{serverUrl:$('#serverUrl').value}});toast('تم حفظ رابط الخادم')});
   $$('.resolve-conflict',p).forEach(b=>b.onclick=()=>run(async()=>{await api(`/sync/conflicts/${b.dataset.id}/resolve`,{method:'POST'});toast('تم حل التعارض');await show('maintenance')},{loading:true}));
  }
  btnIconize(p);
 };
 $$('[data-rpt]').forEach(b=>b.onclick=()=>run(()=>show(b.dataset.rpt)));
 await show('trial');
}
async function renderSettings(){const s=await api('/settings');$('#view').innerHTML=pageHead('الإعدادات والكليشة','هوية الشركة والطباعة والضريبة والعملات',`<button id="saveSettings" data-icon="save">حفظ الإعدادات</button><button class="ghost" id="previewBrand" data-icon="print">معاينة الكليشة</button>`)+`<div class="grid two-col"><div class="panel"><div class="panel-body"><div class="form-grid cols3"><div class="field"><label>اسم الشركة عربي</label><input id="sAr" value="${esc(s.arabic_name)}"/></div><div class="field"><label>اسم الشركة English</label><input id="sEn" value="${esc(s.english_name)}"/></div><div class="field"><label>النشاط</label><input id="sBiz" value="${esc(s.business)}"/></div><div class="field"><label>المدينة</label><input id="sCity" value="${esc(s.city)}"/></div><div class="field"><label>العنوان</label><input id="sAddr" value="${esc(s.address)}"/></div><div class="field"><label>أرقام التواصل</label><input id="sPhones" value="${esc(s.phones)}"/></div><div class="field"><label>واتساب</label><input id="sWhats" value="${esc(s.whatsapp)}"/></div><div class="field"><label>الرقم الضريبي</label><input id="sTaxNo" value="${esc(s.tax_number)}"/></div><div class="field"><label>السجل التجاري</label><input id="sCR" value="${esc(s.commercial_registration)}"/></div><div class="field"><label>العملة</label><input id="sCur" value="${esc(s.currency)}"/></div><div class="field"><label>رمز العملة</label><input id="sCurSym" value="${esc(s.currency_symbol)}"/></div><div class="field"><label>نسبة الضريبة %</label><input id="sTaxRate" type="number" step="0.01" value="${s.tax_rate}"/></div><label class="switch"><input id="sTaxEnabled" type="checkbox" ${s.tax_enabled?'checked':''}/>تفعيل الضريبة</label><label class="switch"><input id="sNegative" type="checkbox" ${s.allow_negative_stock?'checked':''}/>السماح بالمخزون السالب</label><div class="field" style="grid-column:1/-1"><label>تذييل الفاتورة</label><textarea id="sFooter">${esc(s.footer)}</textarea></div></div></div></div><div class="panel"><div class="panel-body"><h3>شعار الشركة</h3><div class="logo-preview" id="logoPreview">${s.logo_data?`<img src="${s.logo_data}"/>`:'<span>بدون شعار</span>'}</div><input id="logoFile" type="file" accept="image/*" style="margin-top:10px"/><p class="muted">تظهر الكليشة والشعار والمدينة والهواتف والرقم الضريبي في 80mm وA4 مع QR قابل للمسح.</p></div></div></div>`;let logo=s.logo_data||'';$('#logoFile').onchange=e=>{const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{logo=rd.result;$('#logoPreview').innerHTML=`<img src="${logo}"/>`};rd.onerror=()=>toast('خطأ قراءة الشعار',rd.error?.message||'تعذر قراءة الملف','error');rd.readAsDataURL(f)};const payload=()=>({arabicName:$('#sAr').value,englishName:$('#sEn').value,business:$('#sBiz').value,city:$('#sCity').value,address:$('#sAddr').value,phones:$('#sPhones').value,whatsapp:$('#sWhats').value,taxNumber:$('#sTaxNo').value,commercialRegistration:$('#sCR').value,footer:$('#sFooter').value,currency:$('#sCur').value,currencySymbol:$('#sCurSym').value,taxEnabled:$('#sTaxEnabled').checked,taxRate:+$('#sTaxRate').value,allowNegativeStock:$('#sNegative').checked,logoData:logo});$('#saveSettings').onclick=()=>run(async()=>{await api('/settings',{method:'POST',body:payload()});toast('تم حفظ الإعدادات','الكليشة والشعار محفوظان في SQLite');await loadBoot();renderSettings()},{loading:true});$('#previewBrand').onclick=()=>{const p=payload();modal('معاينة الكليشة',`<div class="print-sheet a4"><div class="print-header">${p.logoData?`<img class="logo" src="${p.logoData}"/>`:''}<h2>${esc(p.arabicName)}</h2><div>${esc(p.business)}</div><div>${esc(p.city)} — ${esc(p.address)}</div><div>${esc(p.phones)} · WhatsApp ${esc(p.whatsapp)}</div><div>الرقم الضريبي: ${esc(p.taxNumber)} · السجل: ${esc(p.commercialRegistration)}</div></div><h3>نموذج طباعة رسمي A4</h3><p>${esc(p.footer)}</p></div>`,{wide:true})}}

async function openInvoicePrint(id,size='a4'){const x=await run(()=>api('/print/invoice/'+id+'?'+qs({size})),{loading:true});let current=size;const renderSheet=()=>`<div class="print-sheet ${current==='thermal'?'thermal':'a4'}"><div class="print-header">${x.settings.logo_data?`<img class="logo" src="${x.settings.logo_data}"/>`:''}<h2>${esc(x.settings.arabic_name)}</h2><div>${esc(x.settings.business)}</div><div>${esc(x.settings.city)} · ${esc(x.settings.address)}</div><div>${esc(x.settings.phones)} · WhatsApp ${esc(x.settings.whatsapp)}</div><div>الرقم الضريبي: ${esc(x.settings.tax_number)}</div></div><div class="print-meta"><span>فاتورة: <b>${esc(x.invoice.number)}</b></span><span>التاريخ: ${dte(x.invoice.date)}</span><span>الطرف: ${esc(x.invoice.partner_name||'نقدي')}</span></div><table class="print-table"><thead><tr><th>#</th><th>الصنف</th><th>الوحدة</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${x.lines.map((l,i)=>`<tr><td>${i+1}</td><td>${esc(l.item_name)}</td><td>${esc(l.unit_name)}</td><td>${fmt3(l.quantity)}</td><td>${fmt(l.unit_price)}</td><td>${fmt(l.line_total)}</td></tr>`).join('')}</tbody></table><div style="display:flex;justify-content:space-between;align-items:end;margin-top:12px"><div><div>قبل الضريبة: ${fmt(x.invoice.subtotal)}</div><div>الضريبة: ${fmt(x.invoice.tax)}</div><strong>الصافي: ${fmt(x.invoice.total)} ${esc(x.settings.currency_symbol)}</strong></div><img class="print-qr" src="${x.qr}"/></div><div class="print-footer">${esc(x.settings.footer)}</div></div>`;const m=modal('معاينة الطباعة',`<div id="printSheet">${renderSheet()}</div>`,{wide:true,foot:`<button id="doPrint" data-icon="print">طباعة / PDF</button><button class="ghost" id="toggleSize" data-icon="file">تبديل ${size==='thermal'?'A4':'80mm'}</button>`,onOpen:root=>{$('#doPrint',root).onclick=()=>window.print();$('#toggleSize',root).onclick=e=>{current=current==='thermal'?'a4':'thermal';$('#printSheet',root).innerHTML=renderSheet();e.currentTarget.innerHTML=icon('file')+` تبديل ${current==='thermal'?'A4':'80mm'}`}}});return m}
async function openVoucherPrint(id,size='a4'){const x=await run(()=>api('/print/voucher/'+id+'?'+qs({size})),{loading:true});modal('معاينة السند',`<div class="print-sheet ${size==='thermal'?'thermal':'a4'}"><div class="print-header">${x.settings.logo_data?`<img class="logo" src="${x.settings.logo_data}"/>`:''}<h2>${esc(x.settings.arabic_name)}</h2><div>${esc(x.settings.city)} · ${esc(x.settings.phones)}</div></div><h2 style="text-align:center">${x.voucher.kind==='receipt'?'سند قبض':'سند صرف'}</h2><div class="print-meta"><span>${esc(x.voucher.number)}</span><span>${dte(x.voucher.date)}</span></div><p>الطرف: ${esc(x.voucher.partner_name||'-')}</p><p>البيان: ${esc(x.voucher.description)}</p><h3>المبلغ: ${fmt(x.voucher.amount)} ${esc(x.settings.currency_symbol)}</h3><img class="print-qr" src="${x.qr}"/><div class="print-footer">${esc(x.settings.footer)}</div></div>`,{wide:true,foot:`<button onclick="window.print()" data-icon="print">طباعة / PDF</button>`})}

async function globalSearch(q){q=q.trim();const box=$('#globalSuggestions');if(q.length<2){box.classList.remove('show');return}const [items,partners,invs]=await Promise.all([api('/items?'+qs({q})),api('/partners?'+qs({q})),api('/invoices')]);const filteredInv=invs.filter(x=>x.number.toLowerCase().includes(q.toLowerCase())||(x.partner_name||'').toLowerCase().includes(q.toLowerCase())).slice(0,5);const out=[...items.slice(0,5).map(x=>({kind:'صنف',label:x.name,sub:x.sku,route:'items'})),...partners.slice(0,5).map(x=>({kind:x.type==='Customer'?'عميل':'مورد',label:x.name,sub:x.phone,route:'partners'})),...filteredInv.map(x=>({kind:'فاتورة',label:x.number,sub:fmt(x.total),route:x.kind==='sale'?'sales':'purchases'}))];box.innerHTML=out.map((x,i)=>`<div class="suggestion" data-gs="${i}"><span class="kpi-icon blue" style="width:30px;height:30px">${icon(x.kind==='صنف'?'items':x.kind==='فاتورة'?'file':'users')}</span><strong>${esc(x.label)}</strong><small>${esc(x.kind)} · ${esc(x.sub||'')}</small></div>`).join('')||`<div class="suggestion muted">لا توجد نتائج</div>`;box.classList.add('show');$$('[data-gs]',box).forEach(b=>b.onclick=()=>{navigate(out[+b.dataset.gs].route);box.classList.remove('show');$('#globalSearch').value=''})}

function currentNew(){if(state.route==='items')openItemModal();else if(state.route==='partners')openPartnerModal(state.partnerType);else if(state.route==='sales'||state.route==='purchases'){const k=state.route==='sales'?'sale':'purchase';state.invoice[k]=newInvoiceState(k);renderInvoice(k)}else if(state.route==='vouchers')openVoucherModal('receipt');else if(state.route==='accounts')openJournalModal();else navigate('sales')}
async function shortcut(e){if(e.key==='F2'){e.preventDefault();currentNew()}if(e.key==='F3'){e.preventDefault();$('#globalSearch').focus();$('#globalSearch').select()}if(e.key==='F5'){e.preventDefault();if(state.route==='sales'||state.route==='purchases')$('#postInvoice')?.click();else if(state.route==='settings')$('#saveSettings')?.click()}if(e.key==='F7'){e.preventDefault();if(state.route==='partners'&&state.partners[0])openPartnerStatement(state.partners[0]);else navigate('partners')}if(e.key==='F8'){e.preventDefault();if(state.route==='sales'||state.route==='purchases')$('#invoicePrint80')?.click()}if(e.key==='F9'){e.preventDefault();await run(async()=>{const s=await api('/sync');toast('حالة المزامنة',s.serverUrl?`الخادم: ${s.serverUrl}`:'الوضع محلي — لم يحدد خادم')})}}

async function init(){buildNav();$('#searchIcon').innerHTML=icon('search');$('#menuBtn').innerHTML=icon('menu');btnIconize();$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#themeBtn').onclick=()=>{const dark=document.documentElement.dataset.theme==='dark';document.documentElement.dataset.theme=dark?'light':'dark';$('#themeBtn').innerHTML=icon(dark?'moon':'sun');storageSet('qodynex-theme',dark?'light':'dark')};const saved=storageGet('qodynex-theme');if(saved)document.documentElement.dataset.theme=saved;$('#themeBtn').innerHTML=icon(document.documentElement.dataset.theme==='dark'?'sun':'moon');$('#newBtn').onclick=currentNew;$('#syncBtn').onclick=()=>shortcut({key:'F9',preventDefault(){}});let searchTimer;$('#globalSearch').oninput=e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>run(()=>globalSearch(e.target.value)),180)};document.addEventListener('keydown',shortcut);document.addEventListener('click',e=>{if(!e.target.closest('.global-search'))$('#globalSuggestions').classList.remove('show')});await run(async()=>{await loadBoot();buildNav();await render()},{loading:true});}
window.addEventListener('DOMContentLoaded',init);